"""Offline XLSX cleaner. Importing this module performs no work."""
import base64
import copy
import io
import json
import math
import posixpath
import re
import sys
import zipfile
from datetime import date, datetime
from xml.etree import ElementTree as ET

from openpyxl import load_workbook
from openpyxl.utils.datetime import from_excel

S = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
R = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'
P = 'http://schemas.openxmlformats.org/package/2006/relationships'
C = 'http://schemas.openxmlformats.org/package/2006/content-types'
NS = {'s': S}
ET.register_namespace('', S)
ET.register_namespace('r', R)


def tag(name):
    return '{%s}%s' % (S, name)


def xml_bytes(root):
    return ET.tostring(root, encoding='utf-8', xml_declaration=True)


def number(cell):
    value = cell.value
    if cell.data_type in ('f', 'e') or isinstance(value, (bool, date)):
        raise ValueError('Invalid number')
    if value is None or isinstance(value, str) and not value.strip():
        return 0.0
    if isinstance(value, str):
        value = value.strip()
        if not re.fullmatch(r'[+-]?(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[eE][+-]?[0-9]+)?', value):
            raise ValueError('Invalid number')
    result = float(value)
    if not math.isfinite(result):
        raise ValueError('Nonfinite number')
    return result


def normalize_date(cell, epoch):
    value = cell.value
    if value is None or isinstance(value, str) and not value.strip():
        return ''
    if cell.data_type in ('f', 'e') or isinstance(value, bool):
        raise ValueError('Invalid date at ' + cell.coordinate)
    if isinstance(value, (int, float)):
        value = from_excel(value, epoch)
    if isinstance(value, datetime):
        return value.date().isoformat()
    if isinstance(value, date):
        return value.isoformat()
    if isinstance(value, str):
        text = value.strip()
        try:
            return datetime.fromisoformat(text.replace('Z', '+00:00')).date().isoformat()
        except ValueError:
            pass
        for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%m/%d/%Y', '%d/%m/%Y',
                    '%m-%d-%Y', '%d-%m-%Y', '%Y%m%d', '%d-%b-%Y',
                    '%d %b %Y', '%B %d, %Y', '%b %d, %Y'):
            try:
                return datetime.strptime(text, fmt).date().isoformat()
            except ValueError:
                pass
    raise ValueError('Unrecognized date at ' + cell.coordinate)


def set_cell(cell, value, formula=None):
    # Retain style and address; replace only cell content/type.
    for child in list(cell):
        if child.tag in (tag('f'), tag('v'), tag('is')):
            cell.remove(child)
    cell.attrib.pop('t', None)
    if formula is not None:
        ET.SubElement(cell, tag('f')).text = formula
        ET.SubElement(cell, tag('v')).text = repr(value)
    elif isinstance(value, str):
        cell.set('t', 'inlineStr')
        node = ET.SubElement(ET.SubElement(cell, tag('is')), tag('t'))
        node.set('{http://www.w3.org/XML/1998/namespace}space', 'preserve')
        node.text = value
    else:
        cell.set('t', 'n')
        ET.SubElement(cell, tag('v')).text = repr(value)


def sheet_paths(parts):
    book = ET.fromstring(parts['xl/workbook.xml'])
    rels = ET.fromstring(parts['xl/_rels/workbook.xml.rels'])
    targets = {}
    for rel in rels:
        target = rel.get('Target', '')
        targets[rel.get('Id')] = (target.lstrip('/') if target.startswith('/')
                                  else posixpath.normpath(posixpath.join('xl', target)))
    paths = {s.get('name'): targets[s.get('{%s}id' % R)]
             for s in book.find(tag('sheets'))}
    return book, rels, paths


def bold_headers(parts, header):
    styles = ET.fromstring(parts['xl/styles.xml'])
    fonts = styles.find(tag('fonts'))
    xfs = styles.find(tag('cellXfs'))
    replacements = {}
    for cell in header.findall(tag('c')):
        old = int(cell.get('s', '0'))
        if old not in replacements:
            xf = copy.deepcopy(xfs[old])
            font = copy.deepcopy(fonts[int(xf.get('fontId', '0'))])
            bold = font.find(tag('b'))
            if bold is None:
                bold = ET.SubElement(font, tag('b'))
            bold.set('val', '1')
            xf.set('fontId', str(len(fonts)))
            xf.set('applyFont', '1')
            fonts.append(font)
            replacements[old] = str(len(xfs))
            xfs.append(xf)
        cell.set('s', replacements[old])
    fonts.set('count', str(len(fonts)))
    xfs.set('count', str(len(xfs)))
    parts['xl/styles.xml'] = xml_bytes(styles)


def clean_workbook(payload):
    encoded = payload['workbook_b64']
    bound = payload['row_bound']
    if not isinstance(encoded, str) or len(encoded) > 200000:
        raise ValueError('Invalid workbook_b64 size')
    if type(bound) is not int or not 1 <= bound <= 32:
        raise ValueError('row_bound must be an integer from 1 through 32')
    raw = base64.b64decode(encoded, validate=True)
    with zipfile.ZipFile(io.BytesIO(raw)) as archive:
        entries = archive.infolist()
        if len(entries) > 2000 or sum(x.file_size for x in entries) > 20000000:
            raise ValueError('Workbook package too large')
        if len({x.filename for x in entries}) != len(entries):
            raise ValueError('Duplicate package entries')
        parts = {x.filename: archive.read(x) for x in entries}
    for name, content in parts.items():
        lower = name.lower()
        if any(x in lower for x in ('vbaproject', 'externallinks/', 'macrosheets/')):
            raise ValueError('Macros and external workbook links are prohibited')
        if lower.endswith(('.xml', '.rels')):
            if b'<!DOCTYPE' in content.upper() or b'<!ENTITY' in content.upper():
                raise ValueError('DTD/entity declarations are prohibited')
            root = ET.fromstring(content)
            if lower.endswith('.rels') and any(x.get('TargetMode') == 'External' for x in root):
                raise ValueError('External relationships are prohibited')
    book, rels, paths = sheet_paths(parts)
    if 'Data' not in paths:
        raise ValueError('Missing Data sheet')
    wb = load_workbook(io.BytesIO(raw), data_only=False, keep_links=False)
    ws = wb['Data']
    headers = [ws.cell(1, c).value for c in range(1, 6)]
    if headers != ['ID', 'Date', 'Quantity', 'Price', 'Amount']:
        raise ValueError('Expected Data columns: ID, Date, Quantity, Price, Amount')
    data = ET.fromstring(parts[paths['Data']])
    rows = data.find(tag('sheetData'))
    header = next((r for r in rows if r.get('r') == '1'), None)
    if header is None:
        raise ValueError('Missing Data header')
    records = [r for r in rows if int(r.get('r')) > 1 and
               any(ws[c.get('r')].value is not None for c in r.findall(tag('c')))]
    if len(records) > bound:
        raise ValueError('Data record count exceeds row_bound')
    seen, retained, amounts = set(), [], []
    for original in records:
        old_row = int(original.get('r'))
        ident = ws.cell(old_row, 1)
        key = (type(ident.value).__name__, ident.value)
        if key in seen:
            continue
        seen.add(key)  # First occurrence wins even if its numbers are invalid.
        try:
            quantity = number(ws.cell(old_row, 3))
            price = number(ws.cell(old_row, 4))
        except (ValueError, TypeError, OverflowError):
            continue
        amount = quantity * price
        if not math.isfinite(amount):
            raise ValueError('Amount exceeds finite numeric range')
        date_text = normalize_date(ws.cell(old_row, 2), wb.epoch)
        new_row = len(retained) + 2
        row = copy.deepcopy(original)
        row.set('r', str(new_row))
        cells = {}
        for cell in row.findall(tag('c')):
            col = re.match(r'[A-Z]+', cell.get('r')).group()
            cell.set('r', col + str(new_row))
            cells[col] = cell
        for col in ('B', 'C', 'D', 'E'):
            if col not in cells:
                cells[col] = ET.SubElement(row, tag('c'), r=col + str(new_row))
        set_cell(cells['B'], date_text)
        set_cell(cells['C'], quantity)
        set_cell(cells['D'], price)
        set_cell(cells['E'], amount, 'C%d*D%d' % (new_row, new_row))
        row[:] = sorted(row, key=lambda c: (len(re.match(r'[A-Z]+', c.get('r')).group()), c.get('r')))
        retained.append(row)
        amounts.append(amount)
    rows[:] = [header] + retained
    last_row = len(retained) + 1
    dimension = data.find(tag('dimension'))
    if dimension is not None:
        dimension.set('ref', 'A1:%s%d' % (ws.cell(1, ws.max_column).column_letter, last_row))
    autofilter = data.find(tag('autoFilter'))
    if autofilter is not None:
        autofilter.set('ref', 'A1:E%d' % last_row)
    bold_headers(parts, header)
    parts[paths['Data']] = xml_bytes(data)
    if 'Summary' in paths:
        summary_path = paths['Summary']
        summary = ET.fromstring(parts[summary_path])
    else:
        number_id = 1
        while 'xl/worksheets/sheet%d.xml' % number_id in parts:
            number_id += 1
        summary_path = 'xl/worksheets/sheet%d.xml' % number_id
        used = {r.get('Id') for r in rels}
        rid = 'rIdSummary'
        while rid in used:
            rid += '_'
        ET.SubElement(rels, '{%s}Relationship' % P, Id=rid,
                      Type=R + '/worksheet', Target='worksheets/sheet%d.xml' % number_id)
        sheets = book.find(tag('sheets'))
        sheet_id = max(int(s.get('sheetId')) for s in sheets) + 1
        ET.SubElement(sheets, tag('sheet'), {'name': 'Summary', 'sheetId': str(sheet_id), '{%s}id' % R: rid})
        types = ET.fromstring(parts['[Content_Types].xml'])
        ET.SubElement(types, '{%s}Override' % C, PartName='/' + summary_path,
                      ContentType='application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml')
        parts['[Content_Types].xml'] = xml_bytes(types)
        summary = ET.Element(tag('worksheet'))
        ET.SubElement(summary, tag('sheetData'))
    sd = summary.find(tag('sheetData'))
    first = next((r for r in sd if r.get('r') == '1'), None)
    if first is None:
        first = ET.Element(tag('row'), r='1')
        sd.insert(0, first)
    for address, value, formula in (
            ('A1', 'Total', None),
            ('B1', sum(amounts), 'SUM(Data!E2:E%d)' % last_row)):
        cell = next((c for c in first if c.get('r') == address), None)
        if cell is None:
            cell = ET.SubElement(first, tag('c'), r=address)
        set_cell(cell, value, formula)
    first[:] = sorted(first, key=lambda c: (len(c.get('r')), c.get('r')))
    dim = summary.find(tag('dimension'))
    if dim is not None:
        summary.remove(dim)  # Optional; readers infer bounds from cells.
    parts[summary_path] = xml_bytes(summary)
    # Remove the now-obsolete calculation dependency chain.
    for rel in list(rels):
        if rel.get('Type', '').endswith('/calcChain'):
            target = rel.get('Target')
            path = target.lstrip('/') if target.startswith('/') else posixpath.normpath('xl/' + target)
            parts.pop(path, None)
            rels.remove(rel)
            types = ET.fromstring(parts['[Content_Types].xml'])
            for item in list(types):
                if item.get('PartName') == '/' + path:
                    types.remove(item)
            parts['[Content_Types].xml'] = xml_bytes(types)
    calc = book.find(tag('calcPr'))
    if calc is None:
        calc = ET.SubElement(book, tag('calcPr'))
    calc.set('calcMode', 'auto')
    calc.set('fullCalcOnLoad', '1')
    parts['xl/workbook.xml'] = xml_bytes(book)
    parts['xl/_rels/workbook.xml.rels'] = xml_bytes(rels)
    output = io.BytesIO()
    with zipfile.ZipFile(output, 'w', zipfile.ZIP_DEFLATED) as archive:
        for name, content in parts.items():
            archive.writestr(name, content)
    result = base64.b64encode(output.getvalue()).decode('ascii')
    if len(result) > 200000:
        raise ValueError('Output exceeds workbook_b64 size limit')
    return {'workbook_b64': result}


def main():
    payload = json.load(sys.stdin)
    json.dump(clean_workbook(payload), sys.stdout, ensure_ascii=False)
    sys.stdout.write('\n')


if __name__ == '__main__':
    main()
